data.nginx.conf:
worker_processes 1;
error_log stderr warn;
events {
    worker_connections 1024;
}
http {
    # Aggregate admission control, not a replacement for authenticated API quotas.
    limit_req_zone $server_name zone=catalog_budget:1m rate=100r/s;
    log_format safe '$request_method $uri status=$status upstream=$upstream_addr';
    access_log /dev/stdout safe;
    map $http_upgrade $connection_upgrade {
        default upgrade;
        '' close;
    }
    upstream main {
        server api-main.g4-api.svc.cluster.local:8080;
    }
    upstream catalog {
        server api-read.g4-api.svc.cluster.local:8080;
    }
    server {
        listen 8080;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Forwarded-For "";
        proxy_connect_timeout 3s;
        proxy_read_timeout 60s;
        # Never replay a payment/write after an ambiguous upstream failure.
        proxy_next_upstream off;

        location = /api/catalog/random {
            limit_except GET { deny all; }
            limit_req zone=catalog_budget burst=20 nodelay;
            limit_req_status 429;
            error_page 429 = @overloaded;
            proxy_pass http://catalog;
        }
        location @overloaded {
            default_type application/json;
            add_header Retry-After 5 always;
            return 429 '{"error":"CapacityExceeded","retryAfterSeconds":5}';
        }
        location /hubs/commerce {
            proxy_set_header Upgrade $http_upgrade;
            proxy_set_header Connection $connection_upgrade;
            proxy_read_timeout 3600s;
            proxy_pass http://main;
        }
        location / {
            proxy_pass http://main;
        }
    }
}
